package com.ruoyi.warehouse.finance;

import com.ruoyi.warehouse.data.WarehouseRepository;
import com.ruoyi.warehouse.security.WarehouseScope;
import com.ruoyi.warehouse.support.*;
import java.math.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.ruoyi.warehouse.finance.AdjustmentSupport.*;

@Service
public class FinanceAdjustmentService {
    private final WarehouseRepository records;private final WarehouseScope scope;private final FinanceRuleService rules;private final FinanceWorkflowService workflow;private final AdjustmentPolicyService policies;private final AdjustmentSource sources;private final JdbcTemplate jdbc;
    public FinanceAdjustmentService(WarehouseRepository records,WarehouseScope scope,FinanceRuleService rules,FinanceWorkflowService workflow,AdjustmentPolicyService policies){this.records=records;this.scope=scope;this.rules=rules;this.workflow=workflow;this.policies=policies;sources=new AdjustmentSource(records,workflow);jdbc=records.jdbc();}
    @Transactional(readOnly=true) public Map<String,Object> list(String kind,int page,int size,String client){
        rules.permission("query");if(!Set.of("adjustments","creditNotes").contains(kind)||page<1||page>100000||size<1||size>200)throw WarehouseException.invalid("Invalid adjustment list");
        var args=new ArrayList<Object>();args.add(kind);String where="r.kind=? AND "+scope.predicate(kind,args);if(client!=null&&!client.isBlank()){where+=" AND r.client_id=?";args.add(client);}
        if(!scope.admin()){args.add(scope.actor());where+=" AND NOT EXISTS (SELECT 1 FROM wh_reference x JOIN wh_record target ON target.id=x.target_id WHERE (x.owner_id=r.id OR x.owner_id IN (SELECT claim.invoice_id FROM wh_finance_invoice_claim claim JOIN wh_reference fee ON fee.target_id=claim.charge_id WHERE fee.owner_id=r.id AND fee.field_name='charge')) AND (CASE WHEN target.kind='warehouses' THEN target.id ELSE target.warehouse_id END)<>'' AND (CASE WHEN target.kind='warehouses' THEN target.id ELSE target.warehouse_id END) NOT IN (SELECT scope_id FROM wh_user_scope WHERE user_id=? AND scope_type='WAREHOUSE'))";}
        long total=jdbc.queryForObject("SELECT COUNT(*) FROM wh_record r WHERE "+where,Long.class,args.toArray());args.add(size);args.add((long)(page-1)*size);var rows=new ArrayList<Map<String,Object>>();for(String id:jdbc.queryForList("SELECT r.id FROM wh_record r WHERE "+where+" ORDER BY r.created_at DESC,r.id LIMIT ? OFFSET ?",String.class,args.toArray())){var row=records.get(kind,id,false);access(row);rows.add("creditNotes".equals(kind)?creditNote(id):row);}return Map.of("code",200,"msg","success","rows",rows,"total",total);
    }
    @Transactional public Map<String,Object> source(String chargeId){rules.permission("query");lockChargeClient(chargeId);return sourceView(sources.load(chargeId));}
    private Map<String,Object> sourceView(AdjustmentSource.State state){
        var result=new LinkedHashMap<String,Object>();result.put("charge",state.charge());result.put("invoice",state.invoice());result.put("remainingNet",state.remainingNet());result.put("sourceHash",state.sourceHash());result.put("effects",state.effects());
        var components=new ArrayList<Map<String,Object>>();for(var source:state.components()){var row=new LinkedHashMap<>(source);row.put("reduced",state.reduced().getOrDefault(text(row,"id"),BigDecimal.ZERO));row.put("remaining",number(row.get("quantity")).subtract(number(row.get("reduced"))));components.add(row);}result.put("components",components);return result;
    }
    @Transactional public Map<String,Object> create(Map<String,Object> input){
        rules.permission("edit");FinanceInput.keys(input,"requestId","chargeId","reason","evidenceRef");String chargeId=FinanceInput.id(input,"chargeId"),request=FinanceInput.id(input,"requestId");var charge=lockChargeClient(chargeId);String digest=hash(input);var replay=claim(request,"ADJUSTMENT_CREATE",digest);if(replay!=null){access(replay);return replay;}
        var source=sources.load(chargeId);var data=new LinkedHashMap<String,Object>();data.put("client",charge.get("client"));data.put("chargeId",chargeId);data.put("currency",charge.get("currency"));data.put("status","REVIEW");data.put("reason",FinanceInput.text(input,"reason",2000,true));data.put("evidenceRef",FinanceInput.text(input,"evidenceRef",500,true));data.put("sourceHash",source.sourceHash());data.put("createdBy",scope.actor());data.put("requestedAt",Instant.now().toString());
        String id=UUID.randomUUID().toString();var saved=records.write("adjustments",id,data,null,"adjustment:"+id,text(data,"client"));copyReferences(id,charge,source.invoice());records.audit("REQUEST_FINANCIAL_ADJUSTMENT","adjustments",id,null,saved);return complete(request,digest,saved);
    }
    @Transactional public Map<String,Object> get(String id){rules.permission("query");var row=records.get("adjustments",id,false);access(row);lockChargeClient(text(row,"chargeId"));return detail(records.get("adjustments",id,false));}
    private Map<String,Object> detail(Map<String,Object> row){
        var result=new LinkedHashMap<>(row);try{result.put("source",sourceView(sources.load(text(row,"chargeId"))));}catch(WarehouseException e){if(e.getStatus()==403||e.getStatus()==404)throw e;result.put("source",null);result.put("blocker",e.getMessage());}
        result.put("approvals",jdbc.query("SELECT id,actor_id,status,plan_json,plan_hash FROM wh_finance_adjustment_approval WHERE adjustment_id=? ORDER BY created_at,id",(rs,n)->{var plan=WarehouseJson.map(rs.getString(4));if(!hash(plan).equals(rs.getString(5)))throw WarehouseException.conflict("Approval evidence changed");return Map.<String,Object>of("id",rs.getString(1),"actorId",rs.getLong(2),"status",rs.getString(3),"plan",plan);},row.get("id")));
        var notes=new ArrayList<Map<String,Object>>();for(String note:jdbc.queryForList("SELECT n.note_id FROM wh_finance_credit_note n JOIN wh_finance_adjustment_effect e ON e.id=n.effect_id WHERE e.adjustment_id=?",String.class,row.get("id")))notes.add(creditNote(note));result.put("creditNotes",notes);return result;
    }
    @Transactional public Map<String,Object> preview(String id,Map<String,Object> input){rules.permission("query");var row=locked(id);version(row,input);if(!"REVIEW".equals(row.get("status")))throw WarehouseException.conflict("Only adjustments awaiting review can be previewed / 仅待复核的调整可预览");var plan=plan(row,input,"");return Map.of("plan",plan,"quoteHash",hash(plan));}
    @Transactional public Map<String,Object> action(String id,Map<String,Object> input){
        String action=FinanceInput.option(input,"action","","approve","revoke","execute","cancel");rules.permission(switch(action){case "approve","revoke"->"approveAdjustment";case "execute"->"executeAdjustment";default->"edit";});
        FinanceInput.keys(input,"requestId","_version","action","planInput","quoteHash","reason");String request=FinanceInput.id(input,"requestId");var old=locked(id);String digest=hash(Map.of("id",id,"input",input));var replay=claim(request,"ADJUSTMENT_ACTION",digest);if(replay!=null){access(replay);return replay;}version(old,input);
        Map<String,Object> result=switch(action){case "approve"->approve(old,input);case "revoke"->revoke(old,input);case "execute"->execute(old);default->cancel(old,input);};return complete(request,digest,result);
    }
    private Map<String,Object> approve(Map<String,Object> row,Map<String,Object> input){
        if(!"REVIEW".equals(row.get("status")))throw WarehouseException.conflict("Adjustment is not awaiting review");var args=map(input.get("planInput"));version(row,args);var plan=plan(row,args,"");if(!Objects.equals(input.get("quoteHash"),hash(plan)))throw WarehouseException.conflict("Adjustment preview changed; review again / 调整预览已改变，请重新复核");
        String approval=UUID.randomUUID().toString();jdbc.update("INSERT INTO wh_finance_adjustment_approval(id,adjustment_id,actor_id,status,plan_json,plan_hash,input_json) VALUES(?,?,?,'APPROVED',?,?,?)",approval,row.get("id"),scope.actor(),WarehouseJson.write(plan),hash(plan),WarehouseJson.write(args));jdbc.update("INSERT INTO wh_finance_adjustment_lock(charge_id,approval_id) VALUES(?,?)",row.get("chargeId"),approval);
        var data=FinanceInput.business(row);data.put("status","APPROVED");data.put("approvalId",approval);data.put("approvedBy",scope.actor());data.put("approvedAt",Instant.now().toString());var saved=write(row,data);records.audit("APPROVE_FINANCIAL_ADJUSTMENT","adjustments",text(row,"id"),row,saved);return saved;
    }
    private Map<String,Object> revoke(Map<String,Object> row,Map<String,Object> input){
        if(!"APPROVED".equals(row.get("status")))throw WarehouseException.conflict("No active approval to revoke");String reason=FinanceInput.text(input,"reason",2000,true),approval=text(row,"approvalId");if(jdbc.update("UPDATE wh_finance_adjustment_approval SET status='REVOKED' WHERE id=? AND status='APPROVED'",approval)!=1||jdbc.update("DELETE FROM wh_finance_adjustment_lock WHERE charge_id=? AND approval_id=?",row.get("chargeId"),approval)!=1)throw WarehouseException.conflict("Approval reservation changed");
        var data=FinanceInput.business(row);data.put("status","REVIEW");data.remove("approvalId");data.put("revokeReason",reason);var saved=write(row,data);records.audit("REVOKE_FINANCIAL_ADJUSTMENT","adjustments",text(row,"id"),row,saved);return saved;
    }
    private Map<String,Object> cancel(Map<String,Object> row,Map<String,Object> input){if(!"REVIEW".equals(row.get("status")))throw WarehouseException.conflict("Only an unapproved request can be cancelled");var data=FinanceInput.business(row);data.put("status","CANCELLED");data.put("cancelReason",FinanceInput.text(input,"reason",2000,true));var saved=write(row,data);records.audit("CANCEL_FINANCIAL_ADJUSTMENT","adjustments",text(row,"id"),row,saved);return saved;}

    private Map<String,Object> plan(Map<String,Object> row,Map<String,Object> input,String allowed){
        FinanceInput.keys(input,"_version","decisions","reason","reconsiderationOf","reconsiderationReason","issueDate","taxPointDate","accountingPeriod");var state=sources.load(text(row,"chargeId"));if(!Objects.equals(row.get("sourceHash"),state.sourceHash()))throw WarehouseException.conflict("Original fee evidence changed; investigate before adjusting / 原收费证据改变，需先核对");
        unlocked(jdbc,text(row,"chargeId"),allowed);if(state.invoice()!=null)invoiceUnlocked(jdbc,state.invoice(),allowed);
        if(!(input.get("decisions") instanceof List<?> ds)||ds.isEmpty()||ds.size()>500)throw WarehouseException.invalid("Select 1 to 500 component decisions");
        var decisions=new ArrayList<Map<String,Object>>();var used=new TreeMap<String,BigDecimal>();var reduced=new TreeMap<>(state.reduced());var seen=new HashSet<String>();boolean hasReduction=false;
        var retained=new TreeSet<String>();for(var effect:state.effects())if(WarehouseJson.maps(effect.get("decisions")).stream().anyMatch(d->"retain".equals(d.get("decision"))&&number(d.get("quantity")).signum()>0))retained.add(text(effect,"id"));
        var reconsideration=new TreeSet<String>();if(input.containsKey("reconsiderationOf")){if(!(input.get("reconsiderationOf") instanceof List<?> refs)||refs.size()>100)throw WarehouseException.invalid("Invalid reconsideration references");for(Object value:refs){if(!(value instanceof String ref)||!retained.contains(ref)||!reconsideration.add(ref))throw WarehouseException.invalid("Prior retained decision not found / 找不到原保留决定");}}
        for(Object item:ds){var d=map(item);FinanceInput.keys(d,"component","quantity","decision");String key=FinanceInput.text(d,"component",64,true),decision=FinanceInput.option(d,"decision","","reduce","retain");var component=state.components().stream().filter(c->key.equals(c.get("id"))).findFirst().orElseThrow(()->WarehouseException.invalid("Unknown fee component"));BigDecimal qty=number(d.get("quantity"));int scale=((Number)component.get("quantityScale")).intValue();if(qty.stripTrailingZeros().scale()>scale||qty.signum()==0&&!("retain".equals(decision)&&number(component.get("quantity")).signum()==0)||!seen.add(key+":"+decision))throw WarehouseException.invalid("Invalid component quantity or duplicate decision / 项目数量精度不符或决定重复");
            used.merge(key,qty,BigDecimal::add);if(used.get(key).add(state.reduced().getOrDefault(key,BigDecimal.ZERO)).compareTo(number(component.get("quantity")))>0)throw WarehouseException.conflict("Decision exceeds the original remaining quantity / 超出原收费剩余数量");
            if("reduce".equals(decision)){hasReduction=true;reduced.merge(key,qty,BigDecimal::add);var prior=state.effects().stream().filter(e->WarehouseJson.maps(e.get("decisions")).stream().anyMatch(x->key.equals(x.get("component"))&&"retain".equals(x.get("decision"))&&number(x.get("quantity")).signum()>0)).map(e->text(e,"id")).toList();if(!prior.isEmpty()&&(!reconsideration.containsAll(prior)||FinanceInput.text(input,"reconsiderationReason",2000,false).isBlank()))throw WarehouseException.conflict("Reference previous retained decisions and explain the new evidence / 请引用原保留决定并说明重新核减的依据");}
            decisions.add(Map.of("component",key,"quantity",qty,"decision",decision,"description",component.get("description"),"basis",component.get("basis"),"rate",component.get("rate")));
        }
        BigDecimal after=AdjustmentSource.remainingRaw(state.components(),reduced),net=state.remainingNet().subtract(money(after)),tax=state.invoice()==null?BigDecimal.ZERO.setScale(2):tax(state.remainingNet(),state.invoiceLine().get("vatRate")).subtract(tax(money(after),state.invoiceLine().get("vatRate")));
        String route=!hasReduction?"RETAIN":state.invoice()==null?"UNBILLED_REDUCTION":"DRAFT".equals(state.invoice().get("status"))?"DRAFT_REISSUE":"CREDIT_NOTE";var policy=policies.lockedCurrent();Map<String,Object> selectedPolicy=null,profile=null;
        if(policy.get("policy") instanceof Map<?,?>){var p=map(policy.get("policy"));selectedPolicy=new LinkedHashMap<>();for(String k:List.of("version","taxMethod","requireDifferentActor","creditPrefix","seller"))selectedPolicy.put(k,p.get(k));selectedPolicy.put("buyer",map(p.get("buyers")).get(row.get("client")));}
        if("CREDIT_NOTE".equals(route)&&net.add(tax).signum()>0){if(selectedPolicy==null||selectedPolicy.get("buyer")==null)throw WarehouseException.conflict("Configure the credit policy and seller/buyer details first / 请先配置贷项政策及双方主体资料");LocalDate issue=FinanceInput.date(input,"issueDate"),point=FinanceInput.date(input,"taxPointDate");String period=FinanceInput.text(input,"accountingPeriod",7,true);if(issue.isAfter(LocalDate.now(ZoneOffset.UTC))||point.isAfter(LocalDate.now(ZoneOffset.UTC))||!period.matches("\\d{4}-(0[1-9]|1[0-2])"))throw WarehouseException.invalid("Invalid credit document dates or accounting period");profile=Map.of("seller",selectedPolicy.get("seller"),"buyer",selectedPolicy.get("buyer"),"issueDate",issue.toString(),"taxPointDate",point.toString(),"accountingPeriod",period);}
        var plan=new LinkedHashMap<String,Object>();plan.put("adjustmentId",row.get("id"));plan.put("chargeId",row.get("chargeId"));plan.put("client",row.get("client"));plan.put("currency",state.charge().get("currency"));plan.put("route",route);plan.put("sourceHash",state.sourceHash());plan.put("effectSequence",state.effects().size()+1);plan.put("beforeRaw",state.remainingRaw());plan.put("remainingRaw",after);plan.put("beforeNet",state.remainingNet());plan.put("remainingNet",money(after));plan.put("net",net);plan.put("tax",tax);plan.put("amount",net.add(tax));plan.put("decisions",decisions);plan.put("reason",FinanceInput.text(input,"reason",2000,true));plan.put("evidenceRef",row.get("evidenceRef"));plan.put("reconsiderationOf",new ArrayList<>(reconsideration));plan.put("reconsiderationReason",FinanceInput.text(input,"reconsiderationReason",2000,false));plan.put("policyRevision",policy.get("_version"));plan.put("policy",selectedPolicy);plan.put("profile",profile);plan.put("invoiceId",state.invoice()==null?null:state.invoice().get("id"));plan.put("invoiceHash",state.invoice()==null?null:hash(state.invoice()));plan.put("originalInvoice",state.invoice());plan.put("vatRate",state.invoiceLine()==null?null:state.invoiceLine().get("vatRate"));return plan;
    }

    private Map<String,Object> execute(Map<String,Object> row){
        if(!"APPROVED".equals(row.get("status")))throw WarehouseException.conflict("An active approval is required / 需要有效批准");String approval=text(row,"approvalId");var saved=jdbc.queryForMap("SELECT * FROM wh_finance_adjustment_approval WHERE id=? AND adjustment_id=? FOR UPDATE",approval,row.get("id"));if(!"APPROVED".equals(saved.get("status")))throw WarehouseException.conflict("Approval is no longer active");var approved=WarehouseJson.map(String.valueOf(saved.get("plan_json")));if(!hash(approved).equals(saved.get("plan_hash")))throw WarehouseException.conflict("Approval checksum failed");
        boolean different=!(approved.get("policy") instanceof Map<?,?> policy)||!Boolean.FALSE.equals(policy.get("requireDifferentActor"));if(different&&((Number)saved.get("actor_id")).longValue()==scope.actor())throw new WarehouseException(403,"warehouse_adjustment_executor","Approval and execution require different people / 批准和执行必须由不同人员完成");
        var args=WarehouseJson.map(String.valueOf(saved.get("input_json")));var plan=plan(row,args,approval);if(!hash(plan).equals(saved.get("plan_hash")))throw WarehouseException.conflict("Approved evidence changed; revoke and review again / 已批准的依据发生变化，请撤销批准后重新复核");
        String effectId=UUID.randomUUID().toString();var effect=new LinkedHashMap<>(plan);effect.put("id",effectId);effect.put("approvedBy",saved.get("actor_id"));effect.put("executedBy",scope.actor());effect.put("executedAt",Instant.now().toString());
        jdbc.update("INSERT INTO wh_finance_adjustment_effect(id,adjustment_id,approval_id,charge_id,invoice_id,sequence_no,route,net,tax,effect_json,effect_hash) VALUES(?,?,?,?,?,?,?,?,?,?,?)",effectId,row.get("id"),approval,row.get("chargeId"),plan.get("invoiceId"),plan.get("effectSequence"),plan.get("route"),plan.get("net"),plan.get("tax"),WarehouseJson.write(effect),hash(effect));
        var charge=records.get("charges",text(row,"chargeId"),true);String route=text(plan,"route");var charged=FinanceInput.business(charge);charged.put("adjustedAmount",plan.get("remainingNet"));if(Set.of("UNBILLED_REDUCTION","DRAFT_REISSUE").contains(route))charged.put("billableAmount",plan.get("remainingNet"));writeRecord("charges",charge,charged);
        String replacement=null,note=null;if("DRAFT_REISSUE".equals(route))replacement=reissue(plan,effectId);if("CREDIT_NOTE".equals(route)&&money(plan.get("amount")).signum()>0)note=postCredit(row,plan,effectId);
        if(jdbc.update("UPDATE wh_finance_adjustment_approval SET status='EXECUTED' WHERE id=? AND status='APPROVED'",approval)!=1||jdbc.update("DELETE FROM wh_finance_adjustment_lock WHERE charge_id=? AND approval_id=?",row.get("chargeId"),approval)!=1)throw WarehouseException.conflict("Approval reservation changed");
        var data=FinanceInput.business(row);data.put("status","RETAIN".equals(route)?"RETAINED":"EXECUTED");data.put("effectId",effectId);data.put("executedBy",scope.actor());data.put("executedAt",effect.get("executedAt"));data.put("replacementInvoice",replacement);data.put("creditNote",note);var result=write(row,data);records.audit("EXECUTE_FINANCIAL_ADJUSTMENT","adjustments",text(row,"id"),row,Map.of("record",result,"effect",effect));return result;
    }
    private String reissue(Map<String,Object> plan,String effect){
        var old=records.get("invoices",text(plan,"invoiceId"),true);if(!hash(old).equals(plan.get("invoiceHash")))throw WarehouseException.conflict("Invoice changed");var data=FinanceInput.business(old);var lines=new ArrayList<Map<String,Object>>();BigDecimal net=BigDecimal.ZERO,taxTotal=BigDecimal.ZERO;
        for(var original:WarehouseJson.maps(old.get("lines"))){var line=new LinkedHashMap<>(original);if(Objects.equals(line.get("id"),plan.get("chargeId"))){line.put("amount",plan.get("remainingNet"));line.put("tax",tax(money(plan.get("remainingNet")),line.get("vatRate")));}lines.add(line);net=net.add(FinanceInput.money(line.get("amount")));taxTotal=taxTotal.add(FinanceInput.money(line.get("tax")));}
        String id=UUID.randomUUID().toString();data.put("reference","INV-R-"+id);data.put("status","DRAFT");data.put("lines",lines);data.put("net",net);data.put("tax",taxTotal);data.put("amount",net.add(taxTotal));data.put("predecessor",old.get("id"));data.put("adjustmentEffect",effect);data.remove("successor");data.remove("confirmedAt");data.remove("unconfirmedAt");var replacement=records.write("invoices",id,data,null,"invoice:"+id,text(old,"client"));
        var refs=new LinkedHashMap<String,String>();int n=0;for(var ref:jdbc.queryForList("SELECT target_id FROM wh_reference WHERE owner_id=?",String.class,old.get("id")))refs.put("origin"+n++,ref);refs.put("predecessor",text(old,"id"));records.replaceReferences(id,refs);
        for(var line:lines){String cid=text(line,"id");var charge=records.get("charges",cid,true);if(!Objects.equals(charge.get("invoice"),old.get("id"))||jdbc.update("UPDATE wh_finance_invoice_claim SET invoice_id=? WHERE charge_id=? AND invoice_id=?",id,cid,old.get("id"))!=1)throw WarehouseException.conflict("Invoice ownership changed");var changed=FinanceInput.business(charge);changed.put("invoice",id);var updatedCharge=writeRecord("charges",charge,changed);jdbc.update("INSERT INTO wh_finance_invoice_line(invoice_id,charge_id,snapshot_json) VALUES(?,?,?)",id,cid,WarehouseJson.write(Map.of("line",line,"charge",updatedCharge)));}
        var replaced=FinanceInput.business(old);replaced.put("status","SUPERSEDED");replaced.put("successor",id);replaced.put("supersededAt",Instant.now().toString());replaced.put("adjustmentEffect",effect);var prior=writeRecord("invoices",old,replaced);records.audit("REISSUE_ADJUSTED_DRAFT","invoices",text(old,"id"),old,Map.of("previous",prior,"replacement",replacement));return id;
    }
    private String postCredit(Map<String,Object> adjustment,Map<String,Object> plan,String effect){
        var policy=map(plan.get("policy"));String prefix=text(policy,"creditPrefix");jdbc.update("INSERT INTO wh_finance_credit_sequence(prefix,next_value) VALUES(?,1) ON DUPLICATE KEY UPDATE prefix=prefix",prefix);long next=jdbc.queryForObject("SELECT next_value FROM wh_finance_credit_sequence WHERE prefix=? FOR UPDATE",Long.class,prefix);if(next<1||next==Long.MAX_VALUE)throw WarehouseException.conflict("Credit numbering exhausted");String number=prefix+String.format(Locale.ROOT,"%06d",next);jdbc.update("UPDATE wh_finance_credit_sequence SET next_value=next_value+1 WHERE prefix=?",prefix);
        String id=UUID.randomUUID().toString();var invoice=map(plan.get("originalInvoice"));var data=new LinkedHashMap<String,Object>();data.put("number",number);data.put("status","POSTED");data.put("direction","CREDIT");data.put("client",adjustment.get("client"));data.put("chargeId",adjustment.get("chargeId"));data.put("invoiceId",invoice.get("id"));data.put("originalInvoiceReference",invoice.get("reference"));data.put("adjustmentId",adjustment.get("id"));data.put("effectId",effect);for(String key:List.of("currency","net","tax","amount","vatRate","reason","profile","policy","decisions"))data.put(key,plan.get(key));data.put("postedAt",Instant.now().toString());data.put("executedBy",scope.actor());
        var saved=records.write("creditNotes",id,data,null,number,text(adjustment,"client"));copyReferences(id,records.get("charges",text(adjustment,"chargeId"),false),invoice);jdbc.update("INSERT INTO wh_finance_credit_note(note_id,number,invoice_id,effect_id,content_hash) VALUES(?,?,?,?,?)",id,number,invoice.get("id"),effect,hash(data));records.audit("POST_CREDIT_NOTE","creditNotes",id,null,saved);return id;
    }
    public Map<String,Object> creditNote(String id){rules.permission("query");var row=records.get("creditNotes",id,false);access(row);String expected=jdbc.queryForObject("SELECT content_hash FROM wh_finance_credit_note WHERE note_id=?",String.class,id);if(!hash(FinanceInput.business(row)).equals(expected))throw WarehouseException.conflict("Credit note content changed / 贷项通知内容校验失败");return row;}
    void access(Map<String,Object> row){scope.assertRecord(text(row,"kind"),row);var charge=records.get("charges",text(row,"chargeId"),false);workflow.assertAggregate("charges",charge);if(!Objects.equals(row.get("client"),charge.get("client")))throw WarehouseException.forbidden();if(!WarehouseJson.empty(charge.get("invoice")))workflow.assertAggregate("invoices",records.get("invoices",text(charge,"invoice"),false));if(!WarehouseJson.empty(row.get("invoiceId")))workflow.assertAggregate("invoices",records.get("invoices",text(row,"invoiceId"),false));}
    private Map<String,Object> lockChargeClient(String id){var charge=records.get("charges",id,false);workflow.assertAggregate("charges",charge);records.scoped("clients",text(charge,"client"),true);return charge;}
    private Map<String,Object> locked(String id){var row=records.get("adjustments",id,false);access(row);lockChargeClient(text(row,"chargeId"));return records.get("adjustments",id,true);}
    private void copyReferences(String id,Map<String,Object> charge,Map<String,Object> invoice){var refs=new LinkedHashMap<String,String>();refs.put("charge",text(charge,"id"));refs.put("client",text(charge,"client"));int n=0;for(String owner:invoice==null?List.of(text(charge,"id")):List.of(text(charge,"id"),text(invoice,"id")))for(String target:jdbc.queryForList("SELECT target_id FROM wh_reference WHERE owner_id=?",String.class,owner))refs.put("scope"+n++,target);if(invoice!=null)refs.put("invoice",text(invoice,"id"));records.replaceReferences(id,refs);}
    private Map<String,Object> write(Map<String,Object> row,Map<String,Object> data){return writeRecord("adjustments",row,data);}
    private Map<String,Object> writeRecord(String kind,Map<String,Object> row,Map<String,Object> data){String id=text(row,"id"),natural=jdbc.queryForObject("SELECT natural_key FROM wh_record WHERE id=?",String.class,id);return records.write(kind,id,data,((Number)row.get("_version")).longValue(),natural,text(data,"client"));}
    private Map<String,Object> claim(String request,String operation,String digest){jdbc.update("INSERT INTO wh_operation_request(actor_id,request_id,operation_type,request_hash,response_json) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE request_id=request_id",scope.actor(),request,operation,digest,"{}");var row=jdbc.queryForMap("SELECT operation_type,request_hash,response_json FROM wh_operation_request WHERE actor_id=? AND request_id=? FOR UPDATE",scope.actor(),request);if(!operation.equals(row.get("operation_type"))||!digest.equals(row.get("request_hash")))throw WarehouseException.conflict("Request identity already used");var replay=WarehouseJson.map(String.valueOf(row.get("response_json")));return replay.isEmpty()?null:replay;}
    private Map<String,Object> complete(String request,String digest,Map<String,Object> result){if(jdbc.update("UPDATE wh_operation_request SET response_json=? WHERE actor_id=? AND request_id=? AND request_hash=?",WarehouseJson.write(result),scope.actor(),request,digest)!=1)throw WarehouseException.conflict("Request journal changed");return result;}
}
